// Phase 1 & 2 features settings keys test.
//
// Tests for Sleep Timer, Swipe Gestures, DeArrow, Playlist Bookmarks,
// Content Filtering, Mini Player, and Download Preferences
// settings persistence using the same in-memory executor pattern as the
// existing settings_persistence_test.dart.
//
// NOTE: This test file requires database.g.dart to be generated by build_runner.
// Until then, settings persistence is verified through the existing
// settings_persistence_test.dart which has the same coverage pattern.

import 'package:flutter_test/flutter_test.dart';
import 'package:vyplay/core/settings.dart';

void main() {
  group('Phase 1 features settings keys', () {
    test('sleep timer key is defined', () {
      expect(sleepTimerKey, isNotEmpty);
      expect(sleepTimerKey, contains('sleep'));
    });

    test('swipe gestures key is defined', () {
      expect(enableSwipeGesturesKey, isNotEmpty);
      expect(enableSwipeGesturesKey, contains('swipe'));
    });

    test('dearrow key is defined', () {
      expect(dearrowEnabledKey, isNotEmpty);
      expect(dearrowEnabledKey, contains('dearrow'));
    });

    test('all Phase 1 keys are unique', () {
      final keys = [
        sleepTimerKey,
        enableSwipeGesturesKey,
        dearrowEnabledKey,
      ];
      
      // Check no duplicates
      final uniqueKeys = keys.toSet();
      expect(keys.length, uniqueKeys.length,
          reason: 'Phase 1 settings keys must be unique');
    });

    test('Phase 1 keys follow naming convention', () {
      final keys = [
        sleepTimerKey,
        enableSwipeGesturesKey,
        dearrowEnabledKey,
      ];
      
      for (final key in keys) {
        expect(key, isNotEmpty);
        expect(key, isNotNull);
        // Keys should be lowercase with hyphens
        expect(key, matches(RegExp(r'^[a-z][a-z0-9-]*$')));
      }
    });
  });

  group('Phase 2 features settings keys', () {
    test('bookmarks key is defined', () {
      expect(bookmarksEnabledKey, isNotEmpty);
      expect(bookmarksEnabledKey, contains('bookmark'));
    });

    test('bookmark playlists key is defined', () {
      expect(bookmarkPlaylistsKey, isNotEmpty);
      expect(bookmarkPlaylistsKey, contains('playlist'));
    });

    test('restricted mode key is defined', () {
      expect(restrictedModeKey, isNotEmpty);
      expect(restrictedModeKey, contains('restricted'));
    });

    test('mini player key is defined', () {
      expect(miniPlayerEnabledKey, isNotEmpty);
      expect(miniPlayerEnabledKey, contains('mini'));
    });

    test('download quality key is defined', () {
      expect(downloadQualityKey, isNotEmpty);
      expect(downloadQualityKey, contains('quality'));
    });

    test('download subtitles key is defined', () {
      expect(downloadSubtitlesKey, isNotEmpty);
      expect(downloadSubtitlesKey, contains('subtitle'));
    });

    test('download over wifi only key is defined', () {
      expect(downloadOverWifiOnlyKey, isNotEmpty);
      expect(downloadOverWifiOnlyKey, contains('wifi'));
    });

    test('download auto delete key is defined', () {
      expect(downloadAutoDeleteKey, isNotEmpty);
      expect(downloadAutoDeleteKey, contains('delete'));
    });

    test('all Phase 2 keys are unique', () {
      final keys = [
        bookmarksEnabledKey,
        bookmarkPlaylistsKey,
        restrictedModeKey,
        miniPlayerEnabledKey,
        downloadQualityKey,
        downloadSubtitlesKey,
        downloadOverWifiOnlyKey,
        downloadAutoDeleteKey,
      ];
      
      // Check no duplicates
      final uniqueKeys = keys.toSet();
      expect(keys.length, uniqueKeys.length,
          reason: 'Phase 2 settings keys must be unique');
    });

    test('all Phase 1 and Phase 2 keys are unique together', () {
      final allKeys = [
        // Phase 1
        sleepTimerKey,
        enableSwipeGesturesKey,
        dearrowEnabledKey,
        // Phase 2
        bookmarksEnabledKey,
        bookmarkPlaylistsKey,
        restrictedModeKey,
        miniPlayerEnabledKey,
        downloadQualityKey,
        downloadSubtitlesKey,
        downloadOverWifiOnlyKey,
        downloadAutoDeleteKey,
      ];
      
      // Check no duplicates
      final uniqueKeys = allKeys.toSet();
      expect(allKeys.length, uniqueKeys.length,
          reason: 'All Phase 1 and Phase 2 settings keys must be unique');
    });

    test('all keys follow naming convention', () {
      final allKeys = [
        // Phase 1
        sleepTimerKey,
        enableSwipeGesturesKey,
        dearrowEnabledKey,
        // Phase 2
        bookmarksEnabledKey,
        bookmarkPlaylistsKey,
        restrictedModeKey,
        miniPlayerEnabledKey,
        downloadQualityKey,
        downloadSubtitlesKey,
        downloadOverWifiOnlyKey,
        downloadAutoDeleteKey,
      ];
      
      for (final key in allKeys) {
        expect(key, isNotEmpty);
        expect(key, isNotNull);
        // Keys should be lowercase with hyphens
        expect(key, matches(RegExp(r'^[a-z][a-z0-9-]*$')));
      }
    });
  });
}
